require ["fileinto", "copy", "mailbox", "imap4flags", "spamtest", "relational", "comparator-i;ascii-numeric"];

# Spam is filed to Junk and deliberately NOT copied to All Mail, so emptying Junk
# actually frees it. This branch also has to exist: Stalwart's own spam filing at
# ingest.rs:357 is guarded by `mailbox_ids == [INBOX_ID]`, an exact vector equality,
# and any fileinto below would break that equality and silently deliver spam to the
# Inbox. The threshold reproduces Stalwart's own decision exactly -- is_spam() is
# `spam_percentage >= 50`, and spam_status() maps Ham to 1, MaybeSpam(pct) to
# ((pct*10) as i64).clamp(2,9), Spam to 10 and Unknown to 0, so 49 -> 4 and 50 -> 5.
if spamtest :value "ge" :comparator "i;ascii-numeric" "5" {
    addflag "$Junk";
    fileinto "Junk";
} else {
    # :copy leaves the implicit keep intact, so the message lands in BOTH Inbox and
    # All Mail. That is one message in two mailboxes, not two copies: ingest takes a
    # Vec of mailbox ids on a single document. Deleting from Inbox, or the client
    # emptying Trash after its default seven days, only untags one mailbox --
    # expunge.rs destroys a message solely when mailboxes.len() == 1.
    fileinto :copy :create "All Mail";
}
